// pool.go
package main

/*
#cgo CFLAGS: -Wall
#include "pool.h"
*/
import "C"

import (
	"fmt"
	"sync"
	"time"
)

var (
	mu      sync.Mutex
	tasks   = make(map[C.uintptr_t]chan int)
	nextID  C.uintptr_t = 1
)

//export taskCallback
func taskCallback(result C.int, user C.uintptr_t) {
	mu.Lock()
	ch, ok := tasks[user]
	delete(tasks, user)
	mu.Unlock()

	if ok {
		ch <- int(result)
		close(ch)
	}
}

func init() {
	C.pool_init(4)
}

func SubmitTask(data int) (<-chan int, func()) {
	ch := make(chan int, 1)

	mu.Lock()
	id := nextID
	nextID++
	tasks[id] = ch
	mu.Unlock()

	C.pool_submit((*[0]byte)(C.taskCallback), C.uintptr_t(id))

	cancel := func() {
		mu.Lock()
		if ch, exists := tasks[id]; exists {
			delete(tasks, id)
			close(ch)
		}
		mu.Unlock()
	}

	return ch, cancel
}

func main() {
	defer C.pool_shutdown()

	ch1, cancel1 := SubmitTask(5)
	ch2, cancel2 := SubmitTask(10)

	go func() {
		select {
		case result := <-ch1:
			fmt.Printf("Task 1 result: %d\n", result)
		case <-time.After(time.Second):
			fmt.Println("Task 1 timeout")
		}
		cancel1()
	}()

	go func() {
