```go
// utf8.go
package main

// #cgo CFLAGS: -.
// #include "utf8.h"
import "C"
import (
	"errors"
	"sync"
)

func ValidateUTF8(data []byte) (bool, string, error) {
	var errMsg *C.char
	result := C.validate_utf8((*C.uint8_t)(&data[0]), C.size_t(len(data)), &errMsg)

	if result == 0 {
		return true, "", nil
	}

	msg := C.GoString(errMsg)
	C.free(unsafe.Pointer(errMsg))
	return false, msg, errors.New(msg)
}

func ValidateUTF8Concurrently(buffers ...[]byte) []struct {
	valid  bool
	msg    string
	err    error
	wg     *sync.WaitGroup
} {
	var wg sync.WaitGroup
	results := make([]struct {
		valid bool
		msg   string
		err   error
		wg   *sync.WaitGroup
	}, len(buffers))

	for i, buf := range buffers {
		wg.Add(1)
		results[i].wg = &wg
		go func(data []byte, idx int) {
			valid, msg, err := ValidateUTF8(data)
			results[idx].valid = valid
			results[idx].msg = msg
			results[idx].err = err
			wg.Done()
		}(buf, i)
	}

	wg.Wait()
	return results
}

func main() {
	buffer1 := []byte("Hello, World!")
	buffer2 := []byte{0xFF, 0xFE, 0x55}

	results := ValidateUTF8Concurrently(buffer1, buffer2)

	for i, r := range results {
		fmt.Printf("Buffer %d: valid=%v, msg=%s\n", i+1, r.valid, r.msg)
	}
}
