const char* get_json_record(const char* key, int* err){
  if(!key){ if(err) *err = 1; return NULL; }
  const char* json = "{\"key\":\"value\"}";
  char* buf = (char*)malloc(strlen(json) + 1);
  if(!buf){ if(err) *err = 2; return NULL; }
